import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`vet-practice-audit`,heroTitle:`Audit your vet practice in minutes`,heroSubtitle:`Perplexity Computer audits your veterinary site, local visibility, and appointment funnel, then shows exactly what to fix to bring in more pet owners.`,inputUrlCta:`Audit my practice`,inputUrlPlaceholder:`yourvetpractice.com`,inputUrlPrefill:`Go to {url} and run a full digital audit for this veterinary practice. 1) Review the website for service clarity, appointment flow, emergency and wellness information, and mobile conversion issues. 2) Audit the Google Business Profile, reviews, and local SEO setup. 3) Benchmark against top local vet practices for trust signals, service messaging, and offer structure. 4) Recommend the highest-impact changes for appointment requests and local search ranking. 5) Deliver a prioritized action plan with rewritten copy and growth recommendations.`,heroOverlaySteps:[`Reviewing your vet site, service pages, and appointment flow for conversion gaps`,`Auditing reviews, local visibility, and nearby practice positioning`,`Rewriting service messaging and prioritizing the fixes most likely to drive appointments`,`Practice audit, booking improvements, and local SEO recommendations ready to use`],generatingSteps:[`Visiting {url} to review your veterinary website, services, and appointment experience`,`Designing an agent to benchmark local practices and visibility signals`,`Configuring copy rewrites, conversion fixes, and local search recommendations`,`Setting up a prioritized action plan with patient-growth opportunities`],featureSectionTitle:`From website friction to more booked appointments`,featureCardTitles:[`Connects to your practice stack`,`Fixes you can apply now`],featureCardDescriptions:[`Computer separates your practice audit into site review, local SEO, service messaging, and competitor research, then routes each step to the right model.`,`Google Business Profile, Docs, Sheets, and planning tools can all feed one workflow so recommendations and booking fixes stay organized.`,`Homepage rewrites. Booking-flow improvements. Review-response guidance. Local SEO priorities. Computer gives you updates tied to more appointments.`],capabilitySectionTitle:`Your practice growth team, on autopilot`,capabilitySectionSubtitle:`Paste your site, step away, and come back to a clearer plan to win more pet-owner bookings.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review your service pages, appointment flow, trust signals, and mobile UX to find the friction hurting bookings.`},{title:`Local Search Review`,description:`Computer can assess your Google Business Profile, review reputation, and local SEO setup to show where competing practices are winning.`},{title:`Service Messaging`,description:`Computer can rewrite your service copy, reassurance language, and CTA sections so pet owners understand why to contact you now.`},{title:`Connect Your Tools`,description:`Computer can organize findings across Google Business Profile, Docs, Sheets, and planning tools so your staff can execute from one place.`},{title:`Remember Your Practice`,description:`Computer can remember your services, ideal client types, and positioning so future audits start with the context that matters.`},{title:`Watch Local Performance`,description:`Computer can revisit your digital presence over time, flag visibility or booking issues, and recommend the next update most likely to improve growth.`}]});export{t as default};
